styles-base-mixin--wave-animation-mixin-.js:
import { vlWaveAnimationMixin } from '@domg-wc/styles';
import { css } from 'lit';

// vlWaveAnimationMixin geeft enkel de @keyframes met de naam die je meegeeft: drie bolletjes als box-shadow op 10, 20
// en 30px rechts van het element, die om beurten op en neer gaan. De animatie zelf zet je op je eigen klasse.
const waveStyles = css`
    .sb-wave-animation-blue {
        animation: sb-wave-animation-blue infinite 1s linear;
        width: 1rem;
        height: 1rem;
        border-radius: 50%;
    }

    ${vlWaveAnimationMixin('sb-wave-animation-blue', 'lightblue')}
`;

// In een Lit-component zet je waveStyles in static styles; op een gewone pagina voeg je het toe aan het document.
document.adoptedStyleSheets = [...document.adoptedStyleSheets, waveStyles.styleSheet];

styles-base-mixin--focus-outline-mixin-d.js:
import { vlFocusOutlineMixin } from '@domg-wc/styles';
import { css } from 'lit';

// Zoals in de story staat de outline hier altijd: de mixin bevat geen :focus-selector (zie notes). In de componenten
// van Flux staat hij in een :focus-regel van een element dat focus kan krijgen.
const focusStyles = css`
    .sb-focus-outline {
        ${vlFocusOutlineMixin()}
        width: 200px;
        padding: 10px;
        text-align: center;
    }
`;

// In een Lit-component zet je focusStyles in static styles; op een gewone pagina voeg je het toe aan het document.
document.adoptedStyleSheets = [...document.adoptedStyleSheets, focusStyles.styleSheet];
